{"content": "<script setup lang="ts">
import { computed, onMounted, ref } from "vue"

// Milestone-7 stub: after mounting, ask the unauthenticated JSON health
// endpoint whether the API surface is up. Milestone 8 replaces this stub
// with the Kanban board that talks to the authenticated deal endpoints.
type HealthState = "checking" | "ok" | "unreachable"

const health = ref<HealthState>("checking")

const healthLabel = computed(() =>
  health.value === "ok" ? "ok" : health.value === "checking" ? "checking…" : "unreachable"
)

onMounted(async () => {
  try {
    const response = await fetch("/api/health", {
      headers: { accept: "application/json" }
    })
    const body = await response.json()
    health.value = response.ok && body?.status === "ok" ? "ok" : "unreachable"
  } catch {
    health.value = "unreachable"
  }
})
</script>

<template>
  <div
    :data-health="health"
    class="flex flex-col gap-4 rounded-md border border-basalt bg-graphite p-6 shadow-subtle"
  >
    <div class="flex items-center justify-between gap-4">
      <div class="flex items-center gap-3">
        <span
          :class="health === 'ok' ? 'bg-signal-green' : 'bg-fog'"
          class="inline-block size-2 rounded-xs"
          aria-hidden="true"
        />
        <span class="font-mono text-xs uppercase tracking-[0.025em] text-fog">
          API health
        </span>
      </div>
      <span class="font-mono text-sm text-chalk">{{ healthLabel }}</span>
    </div>
    <p class="text-sm font-text tracking-[0.025em] text-fog">
      {{
        health === "ok"
          ? "The JSON API is reachable from this Vue app."
          : "The JSON API is not responding."
      }}
    </p>
  </div>
</template>
", "file_path": "/Users/riza/worktrees/evalcode_dsh_runner/assets/vue/App.vue"}

{"content": "import { afterEach, describe, expect, it, vi } from "vitest"
import { flushPromises, mount } from "@vue/test-utils"
import App from "./App.vue"

function stubHealth(response: { ok: boolean; body: unknown }) {
  vi.stubGlobal(
    "fetch",
    vi.fn().mockResolvedValue({
      ok: response.ok,
      json: () => Promise.resolve(response.body)
    })
  )
}

afterEach(() => {
  vi.unstubAllGlobals()
  document.body.innerHTML = ""
})

describe("the /app Vue scaffold", () => {
  it("boots on the #app mount node (Vue sets data-v-app) and shows health ok", async () => {
    stubHealth({ ok: true, body: { status: "ok" } })

    const host = document.createElement("div")
    host.id = "app"
    document.body.appendChild(host)

    // The real entry point: importing it mounts the app exactly like the
    // <script src="/assets/vue/app.js"> tag on the /app controller page.
    await import("./main")
    await flushPromises()

    // Vue 3 marks the element it mounted on with data-v-app.
    expect(host.getAttribute("data-v-app")).toBe("")
    expect(host.textContent).toContain("ok")
    expect(host.querySelector("[data-health]")?.getAttribute("data-health")).toBe("ok")
  })

  it("shows an unreachable state when /api/health is not available", async () => {
    stubHealth({ ok: false, body: { errors: { detail: "Internal Server Error" } } })

    const wrapper = mount(App)
    await flushPromises()

    expect(wrapper.get("[data-health]").attributes("data-health")).toBe("unreachable")
    expect(wrapper.text()).toContain("The JSON API is not responding.")
  })

  it("requests the unauthenticated /api/health endpoint with JSON accept", async () => {
    stubHealth({ ok: true, body: { status: "ok" } })

    mount(App)
    await flushPromises()

    const fetchMock = vi.mocked(fetch)
    expect(fetchMock).toHaveBeenCalledTimes(1)
    const [url, init] = fetchMock.mock.calls[0] as [string, RequestInit | undefined]
    expect(url).toBe("/api/health")
    expect(init?.headers).toMatchObject({ accept: "application/json" })
  })
})
", "file_path": "/Users/riza/worktrees/evalcode_dsh_runner/assets/vue/App.test.ts"}

