{"content": "// Headless-Chrome (CDP) check: register an account in a real browser,
// open the authenticated /app page served by Phoenix, and confirm the
// Vite-built Vue bundle mounts (data-v-app) and reports health "ok".
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function connectCDP(wsUrl) {
  const ws = new WebSocket(wsUrl)
  await new Promise((res, rej) => {
    ws.onopen = res
    ws.onerror = () => rej(new Error("ws connect failed"))
  })
  let id = 0
  const pending = new Map()
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result)
    }
  }
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const mid = ++id
      pending.set(mid, { resolve, reject })
      ws.send(JSON.stringify({ id: mid, method, params }))
    })
  return { ws, send }
}

async function main() {
  const base = "http://127.0.0.1:4000"
  const targets = await (await fetch("http://127.0.0.1:9223/json/list")).json()
  const page = targets.find((t) => t.type === "page")
  if (!page) throw new Error("no chrome page target")

  const cdp = await connectCDP(page.webSocketDebuggerUrl)
  await cdp.send("Page.enable")
  await cdp.send("Runtime.enable")

  const ready = async () => {
    for (let i = 0; i < 80; i++) {
      const r = await cdp.send("Runtime.evaluate", {
        expression: "document.readyState",
        returnByValue: true
      })
      if (r.result.value === "complete") return
      await sleep(250)
    }
    throw new Error("page never reached readyState complete")
  }

  // 1. Open the register page so the session cookie (with CSRF) is set.
  await cdp.send("Page.navigate", { url: `${base}/accounts/register` })
  await ready()

  // 2. Register via a same-origin fetch; session cookies ride along.
  const email = `vuebrowser${Date.now()}@example.com`
