```js
const CDP = async (wsUrl) => {
  const ws = new WebSocket(wsUrl)
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej })
  let id = 0
  const pending = new Map()
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result)
    }
  }
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const mid = ++id
    pending.set(mid, { resolve, reject })
    ws.send(JSON.stringify({ id: mid, method, params }))
  })
  return { ws, send }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function main() {
  const base = "http://127.0.0.1:4000"
  const list = await (await fetch("http://127.0.0.1:9223/json/list")).json()
  const page = list.find((t) => t.type === "page")
  if (!page) throw new Error("no page target")
  const cdp = await CDP(page.webSocketDebuggerUrl)
  await cdp.send("Page.enable")
  await cdp.send("Runtime.enable")
  await cdp.send("Network.enable")

  // 1. open the register page (sets the CSRF session cookie)
  await cdp.send("Page.navigate", { url: `${base}/accounts/register` })
  await waitForLoad(cdp)

  // 2. register through a same-origin fetch (session cookies are sent)
  const email = `vuebrowser${Date.now()}@example.com`
  const regResult = await cdp.send("Runtime.evaluate", {
    expression: `(async () => {
      const token = document.querySelector('meta[name="csrf-token"]').content;
      const res = await fetch('/accounts/register', {
        method: 'POST',
        headers: {'content-type': 'application/x-www-form-urlencoded', 'x-csrf-token': token},
        body: new URLSearchParams({ 'account[email]': ${JSON.stringify(email)}, 'account[password]': 'super secret 1234' })
      });
      return { status: res.status, url: res.url };
    })()`,
    awaitPromise: true,
    returnByValue: true
  })
  console.log("register:", JSON.stringify(regResult.result.value))

  // 3. navigate to /app and wait for Vue mount
  await cdp.send("Page.navigate", { url: `${base}/app` })
  let mounted = null
  for (let i = 0; i < 40; i++) {
    await sleep(250)
    const evalRes = await cdp.send("Runtime.evaluate", {
      expression: `(() => {
        const el = document.querySelector('#app');
